const e=["Dieu","Voleurs","Secrets","Complots","Religion","Force","Mystère"],t="Pourquoi celui qui possède cette chose devrait-il être le seul à pouvoir la garder ?",n="Dieu des Voleurs et des Secrets",r=["Thorvarus représente les Voleurs et les intrigues.","Il ne représente pas uniquement le vol matériel.","Son domaine englobe tout ce qui est obtenu ou accompli sans être vu.","Un objet dérobé.","Une information dissimulée.","Une identité cachée.","Un marché secret.","Un complot préparé dans l'ombre.","Thorvarus règne sur ce que les mortels préfèrent ne pas montrer."],s=[{label:"Domaines",value:"Voleurs, Secrets, Complots"},{label:"Symboles",value:"Une main gantée, une clé, un masque, un œil fermé, une pièce percée, une silhouette encapuchonnée"}],o=[{title:"Le secret",title_border:"#e8553d",type:"text",content:["Pour Thorvarus, un secret possède une valeur particulière.","Une information connue de tous cesse d'être un secret.","Une information connue d'une seule personne peut devenir une arme.","Ses fidèles considèrent donc la discrétion comme une forme de pouvoir.","Mais garder un secret peut également protéger quelqu'un.","Le domaine de Thorvarus n'est ainsi pas intrinsèquement mauvais."]},{title:"Les voleurs",title_border:"#c2660a",type:"text",content:["Les voleurs sont naturellement associés à Thorvarus, mais son culte ne les considère pas tous de la même manière.","Certains volent pour survivre.","D'autres pour s'enrichir.","D'autres encore parce qu'ils considèrent la propriété comme une invention destinée à protéger les puissants.","Les traditions de Thorvarus ne donnent pas de réponse unique à cette question.","Elles posent plutôt une autre question :"]},{title:"Les complots",title_border:"#6f9fd8",type:"text",content:["Thorvarus représente également les complots.","Une conspiration peut servir un tyran.","Mais elle peut également servir à renverser un tyran.","Une information cachée peut protéger un innocent.","Ou permettre à quelqu'un de manipuler des milliers de personnes.","C'est cette ambiguïté qui rend son culte difficile à définir."]},{title:"Le culte de Thorvarus",title_border:"#e8553d",type:"text",content:["Ses fidèles se retrouvent principalement dans les grandes villes.","Voleurs, espions, contrebandiers, informateurs et conspirateurs peuvent lui rendre hommage.","Les sanctuaires sont souvent dissimulés.","Certains ne sont même connus que par un symbole laissé dans une ruelle ou gravé discrètement sur une porte.","Les prêtres de Thorvarus sont rarement reconnaissables.","C'est parfois précisément leur fonction."]},{title:"Thorvarus et Othar",title_border:"#c2660a",type:"text",content:["Thorvarus entretient une relation évidente avec Othar.","Le marché représente l'échange accepté.","Thorvarus représente celui qui a lieu sans l'accord de l'autre.","Mais les frontières sont parfois floues.","Une négociation peut devenir une manipulation.","Un contrat peut devenir un piège.","Un vol peut parfois être considéré comme une forme d'échange imposé."]},{title:"Thorvarus et Théomis",title_border:"#6f9fd8",type:"text",content:["Thorvarus est naturellement opposé aux principes de Théomis.","L'Ordre repose sur des règles visibles.","Thorvarus prospère dans les espaces que ces règles ne parviennent pas à contrôler.","Pourtant, même les sociétés les plus ordonnées ont besoin de secrets.","C'est pourquoi Thorvarus ne disparaît jamais complètement."]},{title:"Symboles",title_border:"#e8553d",type:"text",content:"Thorvarus est généralement représenté par :"},{title:"",type:"list",content:["Une main gantée","Une clé","Un masque","Un œil fermé","Une pièce percée","Une silhouette encapuchonnée"]},{title:"",type:"text",content:["La clé est son symbole le plus courant.","Elle peut ouvrir une porte.","Mais elle peut aussi révéler ce que quelqu'un voulait garder caché."]},{title:"Aujourd'hui",title_border:"#c2660a",type:"text",content:["Thorvarus est rarement vénéré ouvertement.","Son influence est pourtant présente dans toutes les grandes villes.","On raconte que certains voleurs laissent une pièce derrière eux après un cambriolage réussi.","D'autres affirment qu'il s'agit simplement d'une vieille superstition.","Personne ne sait exactement où commence le culte de Thorvarus et où s'arrête la simple tradition des voleurs."]}],i=["Les Dieux","Othar","Théomis","Phiella","Voleurs","Secrets"],u={tags:e,citation:t,surname:n,presentation:r,infos:s,sections:o,related:i};export{t as citation,u as default,s as infos,r as presentation,i as related,o as sections,n as surname,e as tags};
